#!/bin/bash
# Generate the 13 comic story slides (2 credits each)
cd "$(dirname "$0")/.."
C="Vertical comic-book story panel illustration in EXACTLY the same cute chibi cartoon art style as the reference character sheets (thick dark-brown outlines, bright flat colors, soft cel shading, big expressive eyes), characters must match the references exactly. Dynamic cinematic composition, rich detailed background, fun and exciting for a 9-year-old. Leave some clear empty space near the top for a speech bubble. NO text, NO letters, NO speech bubbles, NO captions, NO panel borders, NO watermark."
A=art-gen/raw; ARLO=art-gen/style-ref.png
run(){ tools/gen.sh "$@" ; }
run s01_lego_world 3:4 "President Business (the evil LEGO tycoon minifigure from the reference) sits behind a huge desk in his giant LEGO-brick office tower in a bright colorful LEGO-brick world, rubbing his claw hands with an evil grin, two black boxy LEGO robot minions beside him, LEGO city outside the window. $C" $A/boss_president_business.png $A/mobs5.png &
run s02_portal 3:4 "President Business (the LEGO minifigure from the reference) leaping dramatically through a swirling purple magic portal, escaping the LEGO world, LEGO bricks flying everywhere, evil laugh. $C" $A/boss_president_business.png &
run s03_montreal 3:4 "President Business (the LEGO minifigure from the reference) landing on a rooftop overlooking Montreal at golden hour, arms raised triumphantly; the skyline shows Mount Royal with its cross, the Olympic Stadium leaning tower, the Jacques Cartier bridge and the St. Lawrence river. $C" $A/boss_president_business.png &
run s04_malgosha 3:4 "Malgosha (the old piglin witch-queen from the reference) in a dark purple throne room holding up her Staff of Dominance; the glowing orange Orb of Dominance on top shows a magical vision of the boy hero (from the other reference) inside the orb. Spooky but fun lighting. $C" $A/boss_malgosha.png $ARLO &
wait
run s05_army 3:4 "President Business (LEGO minifigure from the reference) pointing forward and shouting orders at his evil minion army at night: Minecraft-style zombies, skeletons and creepers, Bad Cop, the evil toaster Toasty, black LEGO robot minions, and a big white ghast floating in the sky. Epic villain army shot. $C" $A/boss_president_business.png $A/mobs1.png $A/boss_bad_cop.png $A/boss_toasty.png $A/boss_ghast.png $A/mobs5.png &
run s06_river 3:4 "The boy hero from the reference running urgently toward big green bushes on the bank of a wide river (Rivière des Prairies) on a sunny day, holding his shorts with a desperate funny face (he really needs to pee), his family's cozy house in the background behind him. Funny kid-friendly moment, nothing inappropriate. $C" $ARLO $A/bg_river.png &
run s07_attack 3:4 "Chaos at a cozy family house: Minecraft-style zombies, skeletons and black LEGO robot minions burst through the door; the family from the references panics: the blonde mom, the grey-haired dad, the dark-haired sister, the auburn-haired sister and the very tall brother, plus a black lab dog, a tuxedo cat, a grey and white cat, a chubby tabby cat and two chihuahuas. Funny cartoon panic, not scary. $C" $A/mom.png $A/papa.png $A/alyzee.png $A/eveah.png art-gen/samples/emery-sheet.png $A/twyla.png $A/lenny.png $A/goose.png $A/marah.png $A/tobi.png $A/zuko.png $A/mobs1.png $A/mobs5.png &
run s08_shrink 3:4 "A glowing green ray zaps a real house and shrinks it into a tiny LEGO-brick house; black LEGO robot minions carry the tiny LEGO house away, and drag a cage holding the sad family (blonde mom, grey-haired dad, two sisters, very tall brother) and their pets (black lab, tuxedo cat, grey-white cat, chubby tabby, two chihuahuas). $C" $A/mobs5.png $A/mom.png $A/papa.png $A/alyzee.png $A/eveah.png art-gen/samples/emery-sheet.png $A/twyla.png $A/lenny.png $A/zuko.png &
wait
run s09_empty 3:4 "The boy hero from the reference standing shocked with jaw dropped in front of an empty patch of dirt where his house used to be, by the river, a single folded paper note lying on the ground in front of him. Dramatic, a bit sad, sunset sky. $C" $ARLO $A/bg_river.png &
run s10_note 3:4 "Close-up of a crumpled blank paper note held in a kid's hands, pinned with a yellow LEGO brick, with a dramatic dark background with a spotlight. The paper is completely blank (no writing). $C" $ARLO &
run s11_determined 3:4 "The boy hero from the reference in a heroic low-angle pose, tying a red karate headband around his forehead, fists clenched, determined fierce face, white karate belt, epic glowing orange and purple sky with speed lines behind him, wind in his hair. $C" $ARLO &
run s12_nana_papi 3:4 "The boy hero from the reference hugging his grandmother Nana (long strawberry-blonde hair, dark round sunglasses, white cane) in a cozy kitchen, while his grandfather Papi (dark hair, colorful plaid shirt, big smile) holds out a plate of food from the stove. Warm, loving, happy. $C" $ARLO $A/nana.png $A/papi.png $A/bg_hub.png &
wait
MODEL=gpt_image_2_6 tools/gen.sh s13_title 3:4 "Mobile game title screen art: a big bold cartoon game logo that reads exactly \"ARLO'S AWESOME ADVENTURE\" with a small star badge reading \"AAA\", purple, gold and white chunky lettering with thick dark outlines; below it the boy hero from the reference in a karate fighting pose with a red headband, surrounded by his pets (black lab, tuxedo cat, two chihuahuas) and the Montreal skyline behind, sparkles. Same cute chibi cartoon style as the reference." $ARLO $A/twyla.png $A/lenny.png $A/zuko.png
